// api/Courts/CourtsEndpoints.cs, in a copy of src/appkit/template/ (vendor/ included).
public static void MapCourts(this RouteGroupBuilder api)
{
    var courts = api.MapGroup("courts").WithTags("Courts");
    courts.MapGet("", ListAsync)
        .WithName("listCourts")
        .WithDescription("Every court, with whether it is free now.");
}

// api/Program.cs
var api = app.UseEndgameApp();
api.MapCourts();

import { useApiQuery } from "@endgame/appkit";
import { EmptyState, FailedState, LoadingState } from "@endgame/appkit/ui";

export function CourtsPage() {
  const courts = useApiQuery<Court[]>("courts");
  if (courts.status === "loading") return <LoadingState label="Loading courts…" />;
  if (courts.status === "failed") return <FailedState error={courts.error} onRetry={courts.reload} />;
  if (courts.data.length === 0) return <EmptyState title="No courts yet" />;
  return <ul data-testid="court-list">{/* … */}</ul>;
}
